import{z as i,x as A,o as r,c as d,q as n,j as o,D as t,d as e,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"土地价值税","description":"","frontmatter":{"title":"土地价值税","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/land-value-tax.md","filePath":"econ/land-value-tax.md","lastUpdated":1791063341000}'),p={name:"econ/land-value-tax.md"};function C(D,a,u,m,c,T){const B=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="土地价值税" tabindex="-1">土地价值税 <a class="header-anchor" href="#土地价值税" aria-label="Permalink to &quot;土地价值税&quot;">​</a></h1><div class="epigraph"><p>土地摆在那里不多不少：对它的纯地租征税，供给曲线一根竖线，超额负担为零——税收理论里少见的免费午餐。</p><footer>—— 据 George《Progress and Poverty》(1879)；Vickrey 对土地税的现代辩护</footer></div><p><a href="/econ/tiebout-sorting">Tiebout 用脚投票</a>说居民对「税收-服务包」敏感，对什么税不敏感？对<strong>纯土地价值税</strong>（LVT）：地不能搬家、不能增产。缺口是讲清为何土地税在超额负担意义上近乎完美，以及它为何仍难落地。本课不涉土地财政的制度史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一般税都扭曲行为：劳动税抑制工作、资本税赶走投资。李嘉图租金的特殊性——供给完全无弹性——使对地租征税不改变任何边际决策。问题拆解：纯地租怎么从「土地价格」里剥离？改良部分（建筑）怎么办？谁在承担？</p><p><span class="marginnote">术语翻译：纯地租（pure rent）= 土地在最优用途上的回报超出其次优用途的部分；location value（区位价值）= 不依赖土地上任何建筑的那部分地价，LVT 只对它征。</span></p><p><span class="marginnote">数字实例：评估地价 100 万（区位价值）+ 建筑 300 万。1% LVT 只对前者征，年税 1 万。同一块地盖仓库还是盖楼，税单不变——改良不被惩罚。对照：对 400 万征 1% 财产税，等于对建筑收了 3 万「惩罚改良税」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>操作三步：<strong>估价</strong>——用周边空地成交价或残值法（总价减建筑重置成本折旧）分出区位价值；<strong>课税</strong>——按区位价值年征固定比率；<strong>过渡</strong>——存量业主的财富缩水需要 grandfathering 或分期。技术上全靠评估系统，这也是为什么丹麦、爱沙尼亚、宾州诸城能局部做，而全国推广卡在评估政治。</p>',9)),(r(),o(l,null,{default:t(()=>[s(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%97%E5%9C%B0%E6%80%BB%E4%BB%B7%E5%80%BC%22%5D%20--%3E%20B%5B%22%E5%89%A5%E7%A6%BB%E5%8C%BA%E4%BD%8D%E4%BB%B7%E5%80%BC%22%5D%0A%20%20B%20--%3E%20C%5B%22%E4%BC%B0%E4%BB%B7%3A%20%E9%82%BB%E8%BF%91%E7%A9%BA%E5%9C%B0%2F%E6%AE%8B%E5%80%BC%E6%B3%95%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%B9%B4%E7%A8%8E%20%3D%20%E7%A8%8E%E7%8E%87%20%C3%97%20%E5%8C%BA%E4%BD%8D%E4%BB%B7%E5%80%BC%22%5D%0A%20%20D%20--%3E%20E%7B%22%E5%AF%B9%E8%A1%8C%E4%B8%BA%E7%9A%84%E5%BD%B1%E5%93%8D%3F%22%7D%0A%20%20E%20--%3E%20F%5B%22%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E2%86%91%20%E7%A9%BA%E5%9C%B0%E6%8C%A4%E5%8E%8B%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%BC%80%E5%8F%91%E6%8F%90%E9%80%9F%2F%E5%AF%86%E5%BA%A6%E6%8F%90%E5%8D%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：土地像剧院里固定的座位——座位票钱涨跌都不改变座位数量，对座位收「占座费」不会让座位消失，只会让占着不坐的人让出来；对「座位上搭的台子」（建筑）收费才会让人少搭台子。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("零超额负担的证明一笔带过：税收楔子 \\(=\\) 供给弹性乘需求反应，供给弹性为零则楔子为零——税完全落在地主（按收税时点持有土地的人）头上，租户与开发者不受影响。第二重效率收益：持有空地等待升值的策略被持有成本打断，土地被迫流向出价最高的用途，城市密度提高、蔓延受抑。第三重：LVT 不资本化进未来税负——税基是"),E("strong",null,"年流量"),e("而非存量，未来加税不会预先砸房价，这与财产税的「自我资本化陷阱」相反。")],-1)),(r(),o(l,null,{default:t(()=>[s(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%E6%97%A0%E8%B0%93%E6%8D%9F%E5%A4%B1%E4%B8%BA%E9%9B%B6%3F%22%7D%20--%3E%20R%5B%22%E4%BE%9B%E7%BB%99%E5%9E%82%E7%9B%B4%3A%20%E5%BC%B9%E6%80%A7%3D0%22%5D%0A%20%20R%20--%3E%20S%5B%22%E7%A8%8E%E6%94%B6%E6%A5%94%E5%AD%90%3D0%22%5D%0A%20%20S%20--%3E%20T%5B%22%E5%85%A8%E7%94%B1%E5%9C%B0%E4%B8%BB%E6%89%BF%E6%8B%85%22%5D%0A%20%20U%7B%22%E9%99%84%E5%B8%A6%E6%94%B6%E7%9B%8A%22%7D%20--%3E%20V%5B%22%E7%A9%BA%E5%9C%B0%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E2%86%91%22%5D%0A%20%20V%20--%3E%20W%5B%22%E5%BC%80%E5%8F%91%E6%8F%90%E9%80%9F%2C%20%E5%AF%86%E5%BA%A6%E2%86%91%22%5D%0A%20%20W%20--%3E%20X%5B%22%E5%9F%8E%E5%B8%82%E8%94%93%E5%BB%B6%E5%8F%97%E6%8A%91%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：把 LVT 与财产税混同——财产税对建筑征的部分就是资本税，会减少住房供给；另一误区是「LVT 会推高房价」：税负落在地主身上使土地价格<strong>下降</strong>约税流的现值，自住购房者反而受益。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>难点全在执行端：区位价值剥离的评估误差、农地与生态地的估值、流动性差的市场的过渡公平。政治经济学的死结：税负集中在持有大量土地者身上，而他们是天然的否决联盟。适用性分级：城市核心区最佳（区位价值占比高），农区与资源区要特殊处理（宅基地与矿权另算）。与现代城市财政的接口：LVT 提供「不扭曲的增长融资」，与 <a href="/econ/tiebout-sorting">Tiebout</a> 的辖区竞争互补——竞争压税率的压力对 LVT 较弱，因为税基搬不走。</p><p><span class="marginnote">直觉类比：征 LVT 像收「风水费」——地段风水是政府修路、建地铁、规划学区带来的，把风水增值的一部分收回来补贴财政，既不惩罚盖楼也不惩罚勤劳，只回收「位置红利」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>供给零弹性 ⇒ 超额负担为零，税负全部落在征税时点的地主。</li><li>只对区位价值征、不对改良征，是 LVT 与财产税的分界线。</li><li>持有成本粉碎囤地策略，密度与产出双升。</li><li>出处：George《Progress and Poverty》1879；Vickrey「The Urban Crisis」演讲集；Oates–Schwab 1997。</li></ul>',6))])}const f=i(p,[["render",C]]);export{h as __pageData,f as default};
